    @android.annotation.SuppressLint("GestureBackNavigation") @Override public void onBackPressed(){back();}
    private void go(String next){if(route.equals(searchTarget)&&next.equals(parentRoute())){returnToSearch();return;}if(next.equals("controls"))controlsParent=route.equals("snooze")?"snooze":"options";if(next.equals("challenge")&&(route.equals("edit")||route.equals("search")))routineDraft=alarm.challenges();route=next;render();}
    private void openSearch(){searchTarget="";route="search";render();}
    private void closeSearch(){alarmSearch.remember();AlarmEditorSearchUi.hideKeyboard(this);searchTarget="";route="edit";render();}
    private void returnToSearch(){AlarmEditorSearchUi.hideKeyboard(this);route="search";searchTarget="";searchAnchor="";render();}
    private void searchResult(AlarmEditorSearchUi.Entry entry){if(!AlarmEditorSearchUi.route(entry.route))return;alarmSearch.remember();searchTarget=entry.route;searchAnchor=entry.anchor;go(entry.route);}
