        if(!searchAnchor.isEmpty()){String anchor=searchAnchor;searchAnchor="";View target=findSearchAnchor(body,anchor);if(target!=null)target.post(()->{if(target.isAttachedToWindow())target.requestRectangleOnScreen(new android.graphics.Rect(0,0,target.getWidth(),target.getHeight()),true);});}if(restoredPicker!=null){Bundle saved=restoredPicker;restoredPicker=null;if("time".equals(saved.getString("sleepPickerKind")))openDialog(()->SleepPicker.time(this,"Alarm time",alarm.hour*60+alarm.minute,value->{alarm.hour=value/60;alarm.minute=value%60;render();}));else if(route.equals("smart")&&"About smart wake-up".equals(saved.getString("sleepPickerTitle")))openDialog(()->AlarmSmartWakeUi.about(this));else {android.view.View row=findSetting(body,saved.getString("sleepPickerTitle"));if(row!=null)row.performClick();}if(settingsDialog instanceof SleepPicker.StateDialog)settingsDialog.onRestoreInstanceState(saved);}
