    private void openQr(int index,MorningCode code){taskIndex=index;qrRequest=UUID.randomUUID().toString();startActivityForResult(QrCodeActivity.enroll(this,code,qrRequest),343);}
    private void qrResult(int result,Intent data){String request=qrRequest;qrRequest="";if(result!=RESULT_OK||data==null||request.isEmpty()||!request.equals(data.getStringExtra("request")))return;try{MorningCode code=MorningCodeJson.decode(new JSONObject(data.getStringExtra("code")));ChallengeRoutine.Task selected=new ChallengeRoutine.Task("QR code",1,0,MathSettings.LEGACY,code);if(taskIndex<0)routineDraft=routineDraft.add(selected);else{if(taskIndex>=routineDraft.tasks.size()||!routineDraft.tasks.get(taskIndex).type.equals("QR code"))throw new IllegalArgumentException("This routine changed. Reopen its code settings.");routineDraft=routineDraft.replace(taskIndex,selected);}route="challenge";render();}catch(Exception invalid){Ui.toast(this,"Morning code settings could not be applied. Reopen the code and try again.");}}
