    private void routineMenu(int index){if(index<0||index>=routineDraft.tasks.size())return;List<String> options=new ArrayList<>();if(index>0)options.add("Move up");if(index<routineDraft.tasks.size()-1)options.add("Move down");if(routineDraft.tasks.size()>1)options.add("Remove task");if(options.isEmpty()){openDialog(()->SleepPicker.message(this,"Keep one task","Add another task before removing this one."));return;}String snapshot=ChallengeRoutineJson.encode(routineDraft).toString();openDialog(()->ChallengeActionRows.actions(this,"Order or remove task "+(index+1),options,selected->{if(!snapshot.equals(ChallengeRoutineJson.encode(routineDraft).toString())){Ui.toast(this,"The routine changed. Reopen task actions.");return;}String action=options.get(selected);routineDraft=action.equals("Move up")?routineDraft.move(index,index-1):action.equals("Move down")?routineDraft.move(index,index+1):routineDraft.remove(index);render();}));}
